func java21IdentifierBits(r rune) uint8 {
	// The ASCII fast path follows the same profile, including currency/connector characters.
	if r < 128 {
		if r == '_' || r == '$' || r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' {
			return 3
		}
		if r >= '0' && r <= '9' {
			return 2
		}
		return 0
	}
	i := sort.Search(len(java21IdentifierRanges), func(i int) bool { return java21IdentifierRanges[i].last >= r })
	if i < len(java21IdentifierRanges) && r >= java21IdentifierRanges[i].first {
		return java21IdentifierRanges[i].bits
	}
	return 0
}
